-- @case 1: [A01] rows inserted in descending key order, keys at the int limits and with gaps: listed by StockItemID ascending; reorder and target levels differ on every row
BEGIN;
DELETE FROM warehouse.stock_item_holdings;
INSERT INTO warehouse.stock_item_holdings ("StockItemID", "QuantityOnHand", "BinLocation", "LastStocktakeQuantity", "LastCostPrice", "ReorderLevel", "TargetStockLevel") VALUES
  ('2147483647', '10', 'A-1', '10', '1.00', '1', '2'),
  ('1000', '10', 'A-1', '10', '1.00', '3', '4'),
  ('0', '10', 'A-1', '10', '1.00', '0', '-1'),
  ('-1', '10', 'A-1', '10', '1.00', '7', '70'),
  ('-2147483648', '10', 'A-1', '10', '1.00', '2147483647', '-2147483648');
CREATE TEMP TABLE pp_actual ON COMMIT DROP AS
SELECT * FROM integration.get_stock_holding_updates();
DO $pp$
DECLARE got text[];
BEGIN
  SELECT array_agg(attname::text ORDER BY attnum) INTO got FROM pg_attribute WHERE attrelid = 'pp_actual'::regclass AND attnum > 0 AND NOT attisdropped;
  IF got IS DISTINCT FROM ARRAY['Quantity On Hand', 'Bin Location', 'Last Stocktake Quantity', 'Last Cost Price', 'Reorder Level', 'Target Stock Level', 'WWI Stock Item ID']::text[] THEN
    RAISE EXCEPTION 'agreed test failed (%): columns are %, expected %', 'test 01 [A01 rows inserted in descending key order, keys at the int limits and with gaps: listed by StockItem…', got, ARRAY['Quantity On Hand', 'Bin Location', 'Last Stocktake Quantity', 'Last Cost Price', 'Reorder Level', 'Target Stock Level', 'WWI Stock Item ID']::text[];
  END IF;
END $pp$;
CREATE TEMP TABLE pp_expected (LIKE pp_actual) ON COMMIT DROP;
INSERT INTO pp_expected VALUES
  ('10', 'A-1', '10', '1', '2147483647', '-2147483648', '-2147483648'),
  ('10', 'A-1', '10', '1', '7', '70', '-1'),
  ('10', 'A-1', '10', '1', '0', '-1', '0'),
  ('10', 'A-1', '10', '1', '3', '4', '1000'),
  ('10', 'A-1', '10', '1', '1', '2', '2147483647');
DO $pp$
DECLARE missing bigint; extra bigint;
BEGIN
  SELECT count(*) INTO missing FROM ((SELECT * FROM pp_expected) EXCEPT ALL (SELECT * FROM pp_actual)) AS d;
  SELECT count(*) INTO extra FROM ((SELECT * FROM pp_actual) EXCEPT ALL (SELECT * FROM pp_expected)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the result', 'test 01 [A01 rows inserted in descending key order, keys at the int limits and with gaps: listed by StockItem…', missing, extra;
  END IF;
END $pp$;
CREATE TEMP TABLE pp_actual_ord ON COMMIT DROP AS
SELECT row_number() OVER () AS pp_ord, pp_r.* FROM (SELECT * FROM integration.get_stock_holding_updates()) AS pp_r;
CREATE TEMP TABLE pp_expected_ord (pp_ord bigint, LIKE pp_actual) ON COMMIT DROP;
INSERT INTO pp_expected_ord VALUES
  (1, '10', 'A-1', '10', '1', '2147483647', '-2147483648', '-2147483648'),
  (2, '10', 'A-1', '10', '1', '7', '70', '-1'),
  (3, '10', 'A-1', '10', '1', '0', '-1', '0'),
  (4, '10', 'A-1', '10', '1', '3', '4', '1000'),
  (5, '10', 'A-1', '10', '1', '1', '2', '2147483647');
DO $pp$
DECLARE got text[]; want text[];
BEGIN
  SELECT array_agg(ROW("WWI Stock Item ID")::text ORDER BY pp_ord) INTO got FROM pp_actual_ord;
  SELECT array_agg(ROW("WWI Stock Item ID")::text ORDER BY pp_ord) INTO want FROM pp_expected_ord;
  IF got IS DISTINCT FROM want THEN
    RAISE EXCEPTION 'agreed test failed (%): rows are not in the order the original returns (order key WWI Stock Item ID)', 'test 01 [A01 rows inserted in descending key order, keys at the int limits and with gaps: listed by StockItem…';
  END IF;
END $pp$;
ROLLBACK;

